/* Пиксельные герои из наших фотографий. */
(function loadCharacterTexture(source) {
  // Texture loader: discard the neutral preview matte connected to the sheet edges.
  // Clothing and face pixels inside each outlined sprite are retained.
  const img=new Image();
  img.onload=()=>{
    try {
      const canvas=document.createElement('canvas');
      canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;
      const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0);
      const pixels=ctx.getImageData(0,0,canvas.width,canvas.height);
      const data=pixels.data,w=canvas.width,h=canvas.height,n=w*h;
      const visited=new Uint8Array(n),queue=new Uint32Array(n);let head=0,tail=0;
      function enqueue(i){if(i<0||i>=n||visited[i])return;visited[i]=1;const k=i*4,r=data[k],g=data[k+1],b=data[k+2];if(Math.max(r,g,b)-Math.min(r,g,b)<12&&Math.min(r,g,b)>72&&Math.max(r,g,b)<231){queue[tail++]=i;data[k+3]=0;}}
      for(let x=0;x<w;x++){enqueue(x);enqueue((h-1)*w+x);}
      for(let y=0;y<h;y++){enqueue(y*w);enqueue(y*w+w-1);}
      while(head<tail){const i=queue[head++],x=i%w;if(x>0)enqueue(i-1);if(x<w-1)enqueue(i+1);enqueue(i-w);enqueue(i+w);}
      ctx.putImageData(pixels,0,0);
      document.documentElement.style.setProperty('--character-sheet',`url("${canvas.toDataURL('image/png')}")`);
      document.documentElement.classList.add('characters-ready');
    } catch {document.documentElement.classList.add('characters-unavailable');}
  };
  img.onerror=()=>document.documentElement.classList.add('characters-unavailable');
  img.src=source;
}
)("data:image/webp;base64,");
